// Isolated checks for scripts/flaky-triage.ts (Week 4 Task 04). node:test, no browser, no network.
// Uses only the SYNTHETIC fixtures in evidence/fixtures/flaky/ (generated by
// scripts/flaky-fixtures.ts). Every call passes --out to a fresh temp folder, so nothing is ever
// written to evidence/raw/ (real run history).
//
//   node --test safety-tests/flaky-triage.test.mjs

import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import {
  copyFileSync,
  existsSync,
  mkdtempSync,
  readdirSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { after, describe, test } from 'node:test';
import { fileURLToPath } from 'node:url';

const ROOT = fileURLToPath(new URL('..', import.meta.url));
const SCRIPT = join(ROOT, 'scripts', 'flaky-triage.ts');
const FIX = 'evidence/fixtures/flaky';
const temps = [];

function tempDir() {
  const d = mkdtempSync(join(tmpdir(), 'flaky-triage-test-'));
  temps.push(d);
  return d;
}
after(() => {
  for (const d of temps) rmSync(d, { recursive: true, force: true });
});

function triage(args, out = tempDir()) {
  const r = spawnSync(process.execPath, [SCRIPT, ...args, '--out', out], {
    cwd: ROOT,
    encoding: 'utf8',
  });
  const lines = r.stdout.trim().split(/\r?\n/);
  return { code: r.status, stdout: r.stdout, stderr: r.stderr, last: lines[lines.length - 1], out };
}

// The printed path is redacted (<home>), so read the one report folder inside this call's --out.
function reportOf(r) {
  assert.match(r.last, /^flaky-triage: exit 0 report: /);
  const dirs = readdirSync(r.out);
  assert.equal(dirs.length, 1, `one report folder in --out: ${dirs.join(', ')}`);
  return readFileSync(join(r.out, dirs[0], 'flaky-report.md'), 'utf8');
}

function assertError(r, code, kind) {
  assert.equal(r.code, code, r.stderr + r.stdout);
  assert.equal(r.last, `flaky-triage: exit ${code} error: ${kind}`);
  assert.match(r.stderr, new RegExp(`^flaky-triage: ERROR ${kind}: `, 'm'));
  assert.deepEqual(existsSync(r.out) ? readdirSync(r.out) : [], [], 'no report folder on error');
}

describe('flaky-triage: synthetic fixtures (exit 0)', () => {
  test('retry-flaky: one flaky execution of two eligible, three attempts', () => {
    const r = triage([`${FIX}/retry-flaky/report.json`]);
    assert.equal(r.code, 0, r.stderr);
    assert.match(r.stdout, /^flaky-triage: SYNTHETIC — not real run history$/m);
    assert.match(
      r.stdout,
      /^retry-flaky executions: 1 of 2 non-skipped executions with retries > 0$/m,
    );
    assert.match(r.stdout, /^attempts: 3 across 2 executions$/m);
    assert.match(r.stdout, /^compared identities: 0 /m);
    assert.match(r.last, /^flaky-triage: exit 0 report: /);
    assert.match(reportOf(r), /^# SYNTHETIC — not real run history — Flaky triage report$/m);
  });

  test('cross-run-same: candidate only, retry path not measurable', () => {
    const r = triage([
      `${FIX}/cross-run-same/run-a/report.json`,
      `${FIX}/cross-run-same/run-b/report.json`,
    ]);
    assert.equal(r.code, 0, r.stderr);
    assert.match(
      r.stdout,
      /^label differs, conditions match where known: \[alpha\] cross\.fixture\.ts › synthetic cross-run › passes in variant a and fails in variant b \(compared in 2 of 2 runs; expected \/ unexpected\)$/m,
    );
    assert.match(r.stdout, /^retry-flaky executions: not measurable/m);
    assert.match(r.stdout, /^differing identities: 1 of 2$/m);
  });

  test('cross-run-changed: different heads, conditions changed', () => {
    const r = triage([
      `${FIX}/cross-run-changed/run-a/report.json`,
      `${FIX}/cross-run-changed/run-b/report.json`,
    ]);
    assert.equal(r.code, 0, r.stderr);
    assert.match(
      r.stdout,
      /^label differs, conditions changed: .*passes in variant a and fails in variant b/m,
    );
    assert.match(reportOf(r), /head: differs — synthetic-head-1 → synthetic-head-2/);
  });

  test('cross-run-untracked: untracked test code, conditions unknown', () => {
    const r = triage([
      `${FIX}/cross-run-untracked/run-a/report.json`,
      `${FIX}/cross-run-untracked/run-b/report.json`,
    ]);
    assert.equal(r.code, 0, r.stderr);
    assert.match(
      r.stdout,
      /^label differs, conditions unknown: .*passes in variant a and fails in variant b/m,
    );
    assert.match(reportOf(r), /test code: unknown — .*untracked/);
  });

  test('cross-run-noprov: no provenance, every field unknown, not synthetic', () => {
    const r = triage([
      `${FIX}/cross-run-noprov/run-a/report.json`,
      `${FIX}/cross-run-noprov/run-b/report.json`,
    ]);
    assert.equal(r.code, 0, r.stderr);
    assert.doesNotMatch(r.stdout, /SYNTHETIC/);
    assert.match(r.stdout, /^label differs, conditions unknown: /m);
    assert.match(reportOf(r), /no provenance\.txt/);
  });

  test('skip-partial: skipped test listed, not counted as differing', () => {
    const r = triage([
      `${FIX}/skip-partial/run-a/report.json`,
      `${FIX}/skip-partial/run-b/report.json`,
    ]);
    assert.equal(r.code, 0, r.stderr);
    assert.match(r.stdout, /^skipped executions: 1 of 4$/m);
    assert.match(r.stdout, /^differing identities: 0 of 1$/m);
    assert.match(r.stdout, /^label skipped in some or all runs: .*skipped in variant a only/m);
    assert.match(reportOf(r), /synthetic: skipped in variant a/);
  });

  test('same-title: four identities, never merged; one failure', () => {
    const r = triage([`${FIX}/same-title/report.json`]);
    assert.equal(r.code, 0, r.stderr);
    assert.match(r.stdout, /^identities: 4 distinct/m);
    const fails = r.stdout
      .split(/\r?\n/)
      .filter((l) => l.startsWith('label ') && l.endsWith('; unexpected)'));
    assert.equal(fails.length, 1, fails.join('\n'));
    assert.match(fails[0], /\[beta\] same-b\.fixture\.ts › synthetic same title › same title/);
  });

  test('stable: no differences; skips separate', () => {
    const r = triage([`${FIX}/stable/run-a/report.json`, `${FIX}/stable/run-b/report.json`]);
    assert.equal(r.code, 0, r.stderr);
    assert.match(r.stdout, /^differing identities: 0 of 2$/m);
    assert.match(r.stdout, /^skipped executions: 2 of 6$/m);
    assert.match(r.stdout, /^stats cross-check: pass/m);
  });
});

describe('flaky-triage: errors never produce a report', () => {
  test('no arguments: exit 1 usage', () => assertError(triage([]), 1, 'usage'));
  test('missing file: exit 1', () =>
    assertError(triage([`${FIX}/missing/report.json`]), 1, 'missing'));
  test('empty file: exit 1', () => assertError(triage([`${FIX}/empty/report.json`]), 1, 'empty'));
  test('directory: exit 1', () => assertError(triage([`${FIX}/stable/run-a`]), 1, 'directory'));
  test('same path twice: exit 1', () =>
    assertError(
      triage([`${FIX}/stable/run-a/report.json`, `${FIX}/stable/run-a/report.json`]),
      1,
      'duplicate-path',
    ));
  test('identical content under another name: exit 1', () => {
    const copy = join(tempDir(), 'copy.json');
    copyFileSync(join(ROOT, FIX, 'stable/run-a/report.json'), copy);
    assertError(triage([`${FIX}/stable/run-a/report.json`, copy]), 1, 'duplicate-content');
  });
  test('synthetic and unmarked inputs mixed: exit 1', () =>
    assertError(
      triage([`${FIX}/stable/run-a/report.json`, `${FIX}/cross-run-noprov/run-a/report.json`]),
      1,
      'mixed-synthetic',
    ));
  test('truncated JSON: exit 2', () =>
    assertError(triage([`${FIX}/malformed/truncated.json`]), 2, 'malformed'));
  test('array at top level: exit 2', () =>
    assertError(triage([`${FIX}/malformed/array-root.json`]), 2, 'malformed'));
  test('not a Playwright report: exit 3', () =>
    assertError(triage([`${FIX}/unsupported/not-playwright.json`]), 3, 'unsupported'));
  test('repeat-each report: exit 3', () =>
    assertError(triage([`${FIX}/unsupported/repeat-each.json`]), 3, 'unsupported'));
  test('sharded report: exit 3', () =>
    assertError(triage([`${FIX}/unsupported/sharded.json`]), 3, 'unsupported'));
  test('output not writable: exit 4', () => {
    const blocker = join(tempDir(), 'a-file');
    writeFileSync(blocker, 'not a folder');
    const r = triage([`${FIX}/stable/run-a/report.json`], join(blocker, 'out'));
    assert.equal(r.code, 4, r.stderr + r.stdout);
    assert.equal(r.last, 'flaky-triage: exit 4 error: output');
  });
});

describe('flaky-triage: fixtures hold no local user path', () => {
  test('every generated fixture file is redacted', () => {
    const user = (process.env.USERNAME || process.env.USER || '').toLowerCase();
    const walk = (d) =>
      readdirSync(d, { withFileTypes: true }).flatMap((e) =>
        e.isDirectory() ? (e.name === 'source' ? [] : walk(join(d, e.name))) : [join(d, e.name)],
      );
    const files = walk(join(ROOT, FIX));
    assert.ok(files.length > 0, 'fixtures exist (run node scripts/flaky-fixtures.ts first)');
    for (const f of files) {
      const text = readFileSync(f, 'utf8').toLowerCase();
      if (user) {
        assert.ok(
          !text.includes(`\\\\${user}\\\\`) && !text.includes(`/${user}/`),
          `user path in ${f}`,
        );
      }
    }
  });
});
